372	    private function encodeMp4(string $input, string $output, array $def, int $timeout): void
373	    {
374	        $ffmpeg = $this->ffmpegBinary();
375	        $resolution = (string) ($def['resolution'] ?? '1280x720');
376	        [$width, $height] = array_map('intval', explode('x', $resolution, 2));
377	        $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
378	        $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
379	
380	        // Scale to fit within resolution bounds while maintaining aspect ratio.
381	        // The scale filter uses -2 to keep dimensions divisible by 2 (required by libx264).
382	        $scaleFilter = "scale='if(gt(iw,{$width}),{$width},-2)':'if(gt(ih,{$height}),{$height},-2)'";
383	
384	        $cmd = [
385	            $ffmpeg, '-y', '-i', $input,
386	            '-vf', $scaleFilter,
387	            '-c:v', 'libx264',
388	            '-b:v', "{$videoBitrate}k",
389	            '-maxrate', ((int) ($videoBitrate * 1.5)).'k',
390	            '-bufsize', ((int) ($videoBitrate * 2)).'k',
391	            '-profile:v', 'main', '-level', '4.0',
392	            '-movflags', '+faststart',
393	            '-c:a', 'aac', '-b:a', "{$audioBitrate}k", '-ar', '44100',
394	            $output,
395	        ];
396	
397	        $output_str = $this->runCommand($cmd, $exitCode, $timeout);
398	
399	        if ($exitCode !== 0) {
400	            throw new \RuntimeException("ffmpeg MP4 encoding failed (exit {$exitCode}): {$output_str}");
401	        }
402	    }
