447	    /**
448	     * Build the adaptive (master) HLS playlist content.
449	     *
450	     * @param  array<string, array<string, mixed>>  $variantDefs
451	     */
452	    private function buildAdaptivePlaylist(array $variantDefs): string
453	    {
454	        $lines = ['#EXTM3U'];
455	
456	        foreach ($variantDefs as $variantKey => $def) {
457	            // Guard against config values containing newlines or special chars
458	            // that would corrupt the line-based M3U8 format.
459	            if (! preg_match('/^[a-zA-Z0-9_-]+$/', (string) $variantKey)) {
460	                throw new \RuntimeException("Invalid video variant key: {$variantKey}");
461	            }
462	
463	            $videoBitrate = (int) ($def['video_bitrate_kbps'] ?? 2000);
464	            $audioBitrate = (int) ($def['audio_bitrate_kbps'] ?? 128);
465	            $bandwidth = ($videoBitrate + $audioBitrate) * 1000;
466	            $resolution = strtoupper((string) ($def['resolution'] ?? '1280x720'));
467	
468	            // Resolution must be WxH (digits only) — e.g. 1280x720, 1920X1080.
469	            if (! preg_match('/^\d+X\d+$/', $resolution)) {
470	                throw new \RuntimeException("Invalid video resolution for variant '{$variantKey}': {$resolution}");
471	            }
472	
473	            $lines[] = "#EXT-X-STREAM-INF:BANDWIDTH={$bandwidth},RESOLUTION={$resolution}";
474	            $lines[] = "{$variantKey}/playlist.m3u8";
475	        }
476	
477	        return implode("\n", $lines)."\n";
478	    }
