480	    private function extractDurationMs(array $probe): int
481	    {
482	        $duration = $probe['format']['duration'] ?? null;
483	        if ($duration === null) {
484	            // Fall back to the first video stream
485	            foreach ($probe['streams'] ?? [] as $stream) {
486	                if (($stream['codec_type'] ?? '') === 'video' && isset($stream['duration'])) {
487	                    $duration = $stream['duration'];
488	                    break;
489	                }
490	            }
491	        }
492	
493	        return $duration !== null ? (int) round((float) $duration * 1000) : 0;
494	    }
