510	    /**
511	     * Run an FFmpeg/FFprobe command via Symfony Process and return combined stdout+stderr.
512	     * $exitCode is set by reference.
513	     *
514	     * Uses array-form Process — each element is passed as a literal argument,
515	     * bypassing the shell entirely and eliminating injection via argument composition.
516	     */
517	    private function runCommand(array $cmd, ?int &$exitCode = null, int $timeout = 30): string
518	    {
519	        $process = new Process($cmd);
520	        $process->setTimeout($timeout);
521	        $process->run();
522	
523	        $exitCode = $process->getExitCode() ?? 0;
524	
525	        return $process->getOutput() . $process->getErrorOutput();
526	    }
