528	    private function removeDir(string $dir): void
529	    {
530	        if (! is_dir($dir)) {
531	            return;
532	        }
533	
534	        foreach (scandir($dir) ?: [] as $file) {
535	            if ($file === '.' || $file === '..') {
536	                continue;
537	            }
538	            $path = "{$dir}/{$file}";
539	            is_dir($path) ? $this->removeDir($path) : @unlink($path);
540	        }
541	
542	        @rmdir($dir);
543	    }
