546	     * Legacy jobs may pass the original file path instead of the media directory.
547	     * Normalize to the directory prefix expected by allFiles().
548	     */
549	    private function normalizeVideoCleanupBasePath(string $basePath): string
550	    {
551	        $normalized = trim($basePath);
552	        if ($normalized === '') {
553	            throw new \RuntimeException('Video cleanup base path cannot be empty.');
554	        }
555	
556	        $leaf = basename($normalized);
557	        if (str_contains($leaf, '.')) {
558	            $normalized = dirname($normalized);
559	        }
560	
561	        $normalized = trim($normalized, '/');
562	        if ($normalized === '' || $normalized === '.') {
563	            throw new \RuntimeException('Video cleanup base path resolved to an invalid directory.');
564	        }
565	
566	        return $normalized;
567	    }
