569	    private function diskName(): string
570	    {
571	        $configured = (string) config('sidest.media_disk', 'media');
572	
573	        // $_ENV/$_SERVER are intentional here — Laravel Cloud caches config at deploy time
574	        // but injects platform env vars directly into the process environment at runtime,
575	        // so env()/config() won't see them. Direct superglobal access bypasses that cache.
576	        $explicit = $_ENV['SIDEST_MEDIA_DISK'] ?? $_SERVER['SIDEST_MEDIA_DISK'] ?? null;
577	        if (is_string($explicit) && trim($explicit) !== '') {
578	            return $configured;
579	        }
580	
581	        if ($configured === 'media') {
582	            $default = (string) config('filesystems.default', 'local');
583	            $defaultConfig = config("filesystems.disks.{$default}");
584	
585	            if (
586	                $default !== '' &&
587	                $default !== 'local' &&
588	                $default !== 'media' &&
589	                is_array($defaultConfig) &&
590	                (($defaultConfig['driver'] ?? null) === 's3')
591	            ) {
592	                return $default;
593	            }
594	        }
595	
596	        return $configured;
597	    }
